<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import PageHeader from'../components/PageHeader.vue';import AppModal from'../components/AppModal.vue';import EmptyState from'../components/EmptyState.vue';import{categoriesApi,transactionsApi}from'../api/resources';import type{Category,Transaction,TransactionType}from'../types';import{currency,shortDate,today}from'../utils/format';import{useApiError}from'../composables/useApiError';defineEmits<{menu:[]}>();const items=ref<Transaction[]>([]),categories=ref<Category[]>([]),modal=ref(false),editing=ref<Transaction|null>(null),loading=ref(true),filter=ref('ALL'),page=ref(0),totalPages=ref(0);const form=reactive({categoryId:0,type:'EXPENSE' as TransactionType,amount:0,date:today(),description:''});const{error,capture}=useApiError();const filtered=computed(()=>filter.value==='ALL'?items.value:items.value.filter(x=>x.type===filter.value));async function load(){loading.value=true;try{const[t,c]=await Promise.all([transactionsApi.list({page:page.value,size:20,sort:'date,desc'}),categoriesApi.list()]);items.value=t.data.content;totalPages.value=t.data.totalPages;categories.value=c.data}finally{loading.value=false}}onMounted(load);function open(item?:Transaction){if(!categories.value.length){error.value='Crea prima una categoria.';return}editing.value=item||null;Object.assign(form,item?{categoryId:item.categoryId,type:item.type,amount:Number(item.amount),date:item.date,description:item.description||''}:{categoryId:categories.value[0].id,type:'EXPENSE',amount:0,date:today(),description:''});error.value='';modal.value=true}async function save(){try{if(editing.value)await transactionsApi.update(editing.value.id,form);else await transactionsApi.create(form);modal.value=false;await load()}catch(e){capture(e)}}async function remove(item:Transaction){if(confirm('Eliminare questo movimento?')){try{await transactionsApi.delete(item.id);await load()}catch(e){capture(e)}}}
</script>
<template><PageHeader title="Movimenti" subtitle="Tutte le entrate e le uscite, in ordine." @menu="$emit('menu')"><button class="btn primary" @click="open()">+ Nuovo movimento</button></PageHeader><div class="toolbar"><div class="segmented"><button v-for="x in ['ALL','INCOME','EXPENSE']" :key="x" :class="{active:filter===x}" @click="filter=x">{{x==='ALL'?'Tutti':x==='INCOME'?'Entrate':'Uscite'}}</button></div></div><div v-if="error&&!modal" class="error">{{error}}</div><div v-if="loading" class="loading">Caricamento…</div><article v-else class="panel table-panel"><div v-if="filtered.length" class="data-table"><div class="table-head"><span>Movimento</span><span>Data</span><span>Tipo</span><span>Importo</span><span></span></div><div v-for="item in filtered" :key="item.id" class="table-row"><span><i class="category-dot" :style="{background:categories.find(c=>c.id===item.categoryId)?.color}"></i><span><b>{{item.description||item.categoryName}}</b><small>{{item.categoryName}}</small></span></span><span>{{shortDate(item.date)}}</span><span><i class="badge" :class="item.type.toLowerCase()">{{item.type==='INCOME'?'Entrata':'Uscita'}}</i></span><strong :class="item.type==='INCOME'?'positive':'negative'">{{item.type==='INCOME'?'+':'−'}} {{currency(Number(item.amount))}}</strong><span class="row-actions"><button @click="open(item)">✎</button><button class="danger" @click="remove(item)">×</button></span></div></div><EmptyState v-else title="Nessun movimento" text="Aggiungi una transazione per iniziare."/><div v-if="totalPages>1" class="pagination"><button :disabled="page===0" @click="page--;load()">←</button><span>Pagina {{page+1}} di {{totalPages}}</span><button :disabled="page>=totalPages-1" @click="page++;load()">→</button></div></article><AppModal v-if="modal" :title="editing?'Modifica movimento':'Nuovo movimento'" @close="modal=false"><form class="modal-form" @submit.prevent="save"><div v-if="error" class="error">{{error}}</div><div class="type-picker"><button type="button" :class="{selected:form.type==='EXPENSE'}" @click="form.type='EXPENSE'">↘ Uscita</button><button type="button" :class="{selected:form.type==='INCOME'}" @click="form.type='INCOME'">↗ Entrata</button></div><label>Importo (€)<input v-model.number="form.amount" type="number" min="0.01" step="0.01" required></label><label>Categoria<select v-model.number="form.categoryId" required><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Data<input v-model="form.date" type="date" required></label><label>Descrizione<textarea v-model="form.description" maxlength="500" placeholder="Aggiungi una nota (opzionale)"></textarea></label><footer><button type="button" class="btn secondary" @click="modal=false">Annulla</button><button class="btn primary">Salva</button></footer></form></AppModal></template>
